:host {
  --ink: #1a1a1a;
  --muted: #666666;
  --accent: #0066cc;
  --warm: #ff6600;
  --line: #e0e0e0;
  --paper: #ffffff;
  --success: #28a745;
  --tech-blue: #0047AB;
  --warning-orange: #FF8C00;
  --success-green: #228B22;
}

.chapter-section {
  max-width: 900px;
  margin: 0 auto 48px auto;
  padding: 24px 16px;
  background: var(--paper);
  border-left: 4px solid var(--tech-blue);
}

.section-title {
  font-size: 24px;
  font-weight: 700;
  color: var(--ink);
  margin: 0 0 20px 0;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--line);
}

.subsection-title {
  font-size: 18px;
  font-weight: 600;
  color: var(--ink);
  margin: 24px 0 16px 0;
}

.body-text {
  font-size: 16px;
  line-height: 1.8;
  color: var(--ink);
  margin: 0 0 16px 0;
  text-align: justify;
}

.content-block {
  margin: 0 0 32px 0;
}

.source-container {
  margin: 16px 0;
}

.source-btn {
  display: inline-block;
  padding: 6px 12px;
  font-size: 13px;
  background: var(--paper);
  border: 1px solid var(--accent);
  color: var(--accent);
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.source-btn:hover {
  background: var(--accent);
  color: var(--paper);
}

.source-btn:focus {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.competitor-comparison {
  background: #f8f9fa;
  padding: 20px;
  border-radius: 8px;
  margin: 24px 0;
}

.comparison-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
  margin: 20px 0;
}

.competitor-card {
  background: var(--paper);
  padding: 16px;
  border-radius: 6px;
  border: 1px solid var(--line);
  text-align: center;
}

.company-name {
  font-size: 15px;
  font-weight: 600;
  color: var(--tech-blue);
  margin: 0 0 8px 0;
}

.station-count {
  font-size: 20px;
  font-weight: 700;
  color: var(--ink);
  margin: 0 0 4px 0;
}

.since-year {
  font-size: 13px;
  color: var(--muted);
  margin: 0 0 4px 0;
}

.service-level {
  font-size: 13px;
  color: var(--success-green);
  font-weight: 500;
}

.limitation-note {
  font-size: 13px;
  color: var(--muted);
  font-style: italic;
  margin: 16px 0 0 0;
  padding: 12px;
  background: #fff3cd;
  border-left: 3px solid var(--warning-orange);
  border-radius: 4px;
}

.interactive-stepper {
  background: #f0f4f8;
  padding: 24px;
  border-radius: 8px;
  margin: 24px 0;
  border: 1px solid var(--line);
}

.teaching-label {
  font-size: 13px;
  color: var(--muted);
  font-style: italic;
  margin: 0 0 16px 0;
  padding: 8px;
  background: #e3f2fd;
  border-left: 3px solid var(--accent);
  border-radius: 4px;
}

.stepper-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin: 0 0 20px 0;
}

.step-btn {
  padding: 10px 20px;
  font-size: 14px;
  background: var(--paper);
  border: 2px solid var(--accent);
  color: var(--accent);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
  font-weight: 500;
}

.step-btn:hover {
  background: var(--accent);
  color: var(--paper);
}

.step-btn:focus {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.step-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--paper);
}

.reset-btn {
  padding: 10px 20px;
  font-size: 14px;
  background: var(--paper);
  border: 2px solid var(--muted);
  color: var(--muted);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
  margin-left: auto;
}

.reset-btn:hover {
  background: var(--muted);
  color: var(--paper);
}

.reset-btn:focus {
  outline: 2px solid var(--muted);
  outline-offset: 2px;
}

.step-display {
  background: var(--paper);
  padding: 20px;
  border-radius: 6px;
  border: 1px solid var(--line);
  min-height: 200px;
}

.step-content {
  display: none;
}

.step-content.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.step-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--tech-blue);
  margin: 0 0 12px 0;
}

.step-text {
  font-size: 15px;
  line-height: 1.7;
  color: var(--ink);
  margin: 0 0 16px 0;
}

.flow-diagram {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 16px;
  background: #f8f9fa;
  border-radius: 6px;
  margin: 16px 0;
}

.flow-node {
  padding: 8px 16px;
  background: var(--tech-blue);
  color: var(--paper);
  border-radius: 4px;
  font-size: 13px;
  font-weight: 500;
}

.flow-node.terminal {
  background: var(--accent);
}

.flow-node.edge {
  background: var(--tech-blue);
}

.flow-node.reference {
  background: var(--warning-orange);
}

.flow-node.result {
  background: var(--success-green);
}

.flow-node.client {
  background: var(--accent);
}

.flow-node.map {
  background: var(--success-green);
}

.flow-arrow {
  font-size: 18px;
  color: var(--muted);
  font-weight: 700;
}

.product-components {
  margin: 24px 0 0 0;
  padding: 20px;
  background: #f8f9fa;
  border-radius: 6px;
}

.component-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.component-list li {
  font-size: 15px;
  line-height: 1.7;
  color: var(--ink);
  margin: 0 0 12px 0;
  padding-left: 20px;
  position: relative;
}

.component-list li:before {
  content: "•";
  position: absolute;
  left: 0;
  color: var(--accent);
  font-weight: 700;
}

.assumptions-box {
  margin: 24px 0 0 0;
  padding: 16px;
  background: #fff3cd;
  border-left: 3px solid var(--warning-orange);
  border-radius: 4px;
}

.assumptions-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--ink);
  margin: 0 0 12px 0;
}

.assumptions-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.assumptions-list li {
  font-size: 14px;
  line-height: 1.6;
  color: var(--ink);
  margin: 0 0 8px 0;
  padding-left: 20px;
  position: relative;
}

.assumptions-list li:before {
  content: "⚠";
  position: absolute;
  left: 0;
  color: var(--warning-orange);
}

.fusion-features {
  margin: 32px 0;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 20px;
  margin: 20px 0;
}

.feature-card {
  background: var(--paper);
  padding: 20px;
  border-radius: 8px;
  border: 1px solid var(--line);
  border-top: 4px solid var(--tech-blue);
}

.feature-number {
  display: inline-block;
  width: 32px;
  height: 32px;
  line-height: 32px;
  text-align: center;
  background: var(--tech-blue);
  color: var(--paper);
  border-radius: 50%;
  font-size: 16px;
  font-weight: 700;
  margin: 0 0 12px 0;
}

.feature-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--ink);
  margin: 0 0 12px 0;
}

.feature-text {
  font-size: 14px;
  line-height: 1.7;
  color: var(--ink);
  margin: 0;
}

.conclusion-takeaway {
  background: #e8f5e9;
  padding: 24px;
  border-radius: 8px;
  border-left: 4px solid var(--success-green);
  margin: 32px 0;
}

.takeaway-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--success-green);
  margin: 0 0 12px 0;
}

.takeaway-text {
  font-size: 16px;
  line-height: 1.7;
  color: var(--ink);
  font-weight: 600;
  margin: 0;
}

.limitations-box {
  margin: 24px 0 0 0;
  padding: 16px;
  background: #fff3cd;
  border-left: 3px solid var(--warning-orange);
  border-radius: 4px;
}

.limitations-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--ink);
  margin: 0 0 12px 0;
}

.limitations-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.limitations-list li {
  font-size: 14px;
  line-height: 1.6;
  color: var(--ink);
  margin: 0 0 8px 0;
  padding-left: 20px;
  position: relative;
}

.limitations-list li:before {
  content: "⚠";
  position: absolute;
  left: 0;
  color: var(--warning-orange);
}

@media (max-width: 480px) {
  .chapter-section {
    padding: 16px 12px;
  }

  .section-title {
    font-size: 20px;
  }

  .body-text {
    font-size: 15px;
  }

  .comparison-grid {
    grid-template-columns: 1fr;
  }

  .stepper-controls {
    flex-direction: column;
  }

  .reset-btn {
    margin-left: 0;
  }

  .flow-diagram {
    flex-direction: column;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }
}
