(function() {
  'use strict';

  const chapterId = 'ch4-market-concl';

  function initStepper() {
    const stepperContainer = document.querySelector('.interactive-stepper');
    if (!stepperContainer) return;

    const stepButtons = stepperContainer.querySelectorAll('.step-btn');
    const stepContents = stepperContainer.querySelectorAll('.step-content');
    const resetBtn = document.getElementById(`${chapterId}-reset`);

    function showStep(stepNumber) {
      stepButtons.forEach(btn => {
        const btnStep = parseInt(btn.getAttribute('data-step'), 10);
        btn.setAttribute('aria-pressed', btnStep === stepNumber ? 'true' : 'false');
      });

      stepContents.forEach(content => {
        const contentStep = parseInt(content.getAttribute('data-step'), 10);
        content.classList.toggle('active', contentStep === stepNumber);
      });
    }

    stepButtons.forEach(btn => {
      btn.addEventListener('click', function() {
        const stepNumber = parseInt(this.getAttribute('data-step'), 10);
        showStep(stepNumber);
      });

      btn.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          const stepNumber = parseInt(this.getAttribute('data-step'), 10);
          showStep(stepNumber);
        }
      });
    });

    if (resetBtn) {
      resetBtn.addEventListener('click', function() {
        showStep(1);
      });

      resetBtn.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          showStep(1);
        }
      });
    }

    showStep(1);
  }

  function initSourceButtons() {
    const sourceButtons = document.querySelectorAll('.source-btn[data-source]');

    sourceButtons.forEach(btn => {
      btn.addEventListener('click', function() {
        const sourceId = this.getAttribute('data-source');
        if (window.paperMindData && window.paperMindData.sources && window.paperMindData.sources[sourceId]) {
          const sourceData = window.paperMindData.sources[sourceId];
          console.log('Source requested:', sourceId, sourceData);
        }
      });

      btn.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          this.click();
        }
      });
    });
  }

  function initKeyboardNavigation() {
    document.addEventListener('keydown', function(e) {
      const activeElement = document.activeElement;

      if (activeElement.classList.contains('step-btn')) {
        const stepButtons = Array.from(document.querySelectorAll('.step-btn'));
        const currentIndex = stepButtons.indexOf(activeElement);

        if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
          e.preventDefault();
          const nextIndex = (currentIndex + 1) % stepButtons.length;
          stepButtons[nextIndex].focus();
        } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
          e.preventDefault();
          const prevIndex = (currentIndex - 1 + stepButtons.length) % stepButtons.length;
          stepButtons[prevIndex].focus();
        }
      }
    });
  }

  function validateData() {
    if (!window.paperMindData) {
      console.warn('paperMindData not available');
      return false;
    }

    const requiredNodes = ['market-solutions', 'cmcc-product', 'conclusion-synthesis'];
    const availableNodes = window.paperMindData.nodes ? window.paperMindData.nodes.map(n => n.id) : [];

    requiredNodes.forEach(nodeId => {
      if (!availableNodes.includes(nodeId)) {
        console.warn(`Node ${nodeId} not found in paperMindData`);
      }
    });

    return true;
  }

  function init() {
    validateData();
    initStepper();
    initSourceButtons();
    initKeyboardNavigation();

    const sections = document.querySelectorAll('.chapter-section');
    sections.forEach(section => {
      const nodeId = section.getAttribute('data-node');
      if (nodeId) {
        section.id = nodeId;
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
